# save
repository.save(new Item("itemA", 10000, 10));

#   Executing prepared SQL statement
#     [insert into item (item_name, price, quantity) values (?, ?, ?)]
#   {1: 'itemA', 2: 10000, 3: 10}
#   generated key = 1

# update
repository.update(1L, new ItemUpdateDto("itemA-updated", 20000, 30));

#   Executing prepared SQL update
#     [update item set item_name=?, price=?, quantity=? where id=?]
#   {1: 'itemA-updated', 2: 20000, 3: 30, 4: 1}
#   -> 1

# findById - 있을 때
repository.findById(1L);

#   Executing prepared SQL query
#     [select id, item_name, price, quantity from item where id = ?]
#   {1: 1}
#   -> Optional[Item(id=1, itemName=itemA-updated, price=20000, quantity=30)]

# findById - 없을 때
repository.findById(999L);

#   [select id, item_name, price, quantity from item where id = ?]
#   {1: 999}
#   EmptyResultDataAccessException  (잡아서 Optional.empty)
#   -> Optional.empty
